export const LoadingGif = ({width = 64, center = true}) => {
    return (
        <img style={{
            width: `${width}px`,
            height: `${width}px`,
            position: `relative`,
            left: center ? `calc(50% - ${width / 2}px)` : '',
            top: center ? `calc(50% - ${width / 2}px)` : '',
        }}
             src="data:image/gif;base64,"/>
    )
};